1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"slices"
11		"sort"
12		"strings"
13		"time"
14	
15		"github.com/entireio/entire-brain/internal/cli/internal/base"
16		"github.com/spf13/cobra"
17	)
18	
19	// repo-identity is the recovery path for repo_identity_conflict.
20	//
21	// A local repository's brain is stored under a key derived from its root path.
22	// Older builds derived that key from the path STRING the caller happened to
23	// supply, so one repository reached through a symlink -- /tmp on macOS is a
24	// symlink to /private/tmp, so this is the default, not an edge case -- could
25	// end up with two stores. resolveRepoStorageSet refuses to guess between them,
26	// which means every repo-scoped command refuses, INCLUDING the deletes that
27	// could clear the duplicate. The repository becomes unusable with no way out
28	// through the tool.
29	//
30	// This command is the way out. It is deliberately the one verb that reads the
31	// storage set WITHOUT the refusal, because a repair tool that is blocked by the
32	// condition it repairs is not a repair tool.
33	//
34	// It never deletes. --keep RENAMES the stores it is not keeping to a
35	// timestamped sibling, so a user who picks the wrong one can pick again by
36	// renaming it back. Merging two brains is not something a command can do
37	// safely -- they are two independent export histories -- so the choice stays
38	// with the person who knows which one they have been using.
39	
40	// repoIdentityConflictSuffix dates the set-aside copy. Two repairs in the same
41	// second would otherwise collide, and a collision that silently overwrote the
42	// first set-aside store would destroy the history this command exists to
43	// preserve.
44	func repoIdentityConflictSuffix(now time.Time) string {
45		return ".conflict-" + now.UTC().Format("20060102T150405Z")
46	}
47	
48	type repoIdentityOptions struct {
49		keep string
50	}
51	
52	func newRepoIdentityCommand(opts Options) *cobra.Command {
53		identityOpts := repoIdentityOptions{}
54		cmd := &cobra.Command{
55			Use:   "repo-identity [path]",
56			Short: "Find and resolve conflicting brain stores",
57			Long: `Repo-identity reports every brain store a local repository resolves to.
58	
59	A repository normally has exactly one. It has more than one when an older build
60	keyed a brain on the path spelling it was addressed by -- a repository reached
61	through a symlinked path (on macOS, anything under /tmp) could acquire a second
62	store that way. While two stores exist, every other command refuses with
63	repo_identity_conflict rather than guess which history is the real one.
64	
65	Run it with no flags to see the stores. Pass --keep <repo-key> to keep one and
66	move the rest aside: the others are RENAMED, not deleted, to a timestamped
67	sibling directory, so nothing is lost and the choice can be undone with mv.`,
68			Args: cobra.MaximumNArgs(1),
69			RunE: func(cmd *cobra.Command, args []string) error {
70				target := "."
71				if opts.Env.RepoRoot != "" {
72					target = opts.Env.RepoRoot
73				}
74				if len(args) == 1 {
75					target = args[0]
76				}
77				return runRepoIdentity(cmd.Context(), cmd, opts, identityOpts, target)
78			},
79		}
80		cmd.Flags().StringVar(&identityOpts.keep, "keep", "",
81			"Repo key of the store to keep; every other store for this repository is moved aside")
82		return cmd
83	}
84	
85	func runRepoIdentity(ctx context.Context, cmd *cobra.Command, opts Options, identityOpts repoIdentityOptions, target string) error {
86		repoDir, local, err := base.ResolveLocalTargetRepoDir(ctx, opts.Runner, target)
87		if err != nil {
88			return err
89		}
90		if !local {
91			return fmt.Errorf("repo-identity requires a local repository path: %s", target)
92		}
93		set, err := resolveRepoStorageSet(ctx, opts.Runner, opts.Env, repoDir)
94		if err != nil {
95			return err
96		}
97		keep := strings.TrimSpace(identityOpts.keep)
98		if keep == "" {
99			return reportRepoIdentity(cmd, set)
100		}
101		return resolveRepoIdentityConflict(cmd, opts, set, keep)
102	}
103	
104	func reportRepoIdentity(cmd *cobra.Command, set repoStorageSet) error {
105		out := cmd.OutOrStdout()
106		fmt.Fprintf(out, "canonical repo key: %s\n", set.Canonical.Key)
107		fmt.Fprintf(out, "canonical brain:    %s\n", set.Canonical.BrainDir)
108		switch len(set.Populated) {
109		case 0:
110			fmt.Fprintln(out, "stores with state:  none (this repository has no brain yet)")
111		case 1:
112			fmt.Fprintf(out, "stores with state:  1 (%s), no conflict\n", set.Populated[0].Key)
113		default:
114			fmt.Fprintf(out, "stores with state:  %d, reported as %s\n", len(set.Populated), localRepoIdentityConflictCode)
115			for _, storage := range set.Populated {
116				fmt.Fprintf(out, "  %s\n    brain: %s\n    head:  %s\n", storage.Key, storage.BrainDir, storage.HeadPath)
117			}
118			fmt.Fprintf(out, "keep one with: %s repo-identity --keep <repo-key>\n", base.SetupCommandPrefix(os.LookupEnv))
119		}
120		return nil
121	}
122	
123	// resolveRepoIdentityConflict keeps one store and renames the others aside.
124	//
125	// Renaming rather than deleting is the whole point: the caller is choosing
126	// between two real histories with only a key to tell them apart, and a wrong
127	// choice must be recoverable with `mv`. os.Rename is also atomic within a
128	// filesystem, so an interrupted repair leaves each store either where it was or
129	// where it was moved to, never half-copied.
130	func resolveRepoIdentityConflict(cmd *cobra.Command, opts Options, set repoStorageSet, keep string) error {
131		keys := make([]string, 0, len(set.Populated))
132		for _, storage := range set.Populated {
133			keys = append(keys, storage.Key)
134		}
135		if !slices.Contains(keys, keep) {
136			sort.Strings(keys)
137			known := "none (this repository has no stored brain)"
138			if len(keys) > 0 {
139				known = strings.Join(keys, ", ")
140			}
141			return fmt.Errorf("--keep %q names no store for this repository; stores holding state: %s", keep, known)
142		}
143		if len(set.Populated) == 1 {
144			fmt.Fprintf(cmd.OutOrStdout(), "%s is already the only store for this repository; nothing to move aside\n", keep)
145			return nil
146		}
147	
148		now := time.Now
149		if opts.Now != nil {
150			now = opts.Now
151		}
152		suffix := repoIdentityConflictSuffix(now())
153		out := cmd.OutOrStdout()
154		var kept repoStorage
155		for _, storage := range set.Populated {
156			if storage.Key == keep {
157				kept = storage
158				continue
159			}
160			if err := moveRepoStorageAside(out, storage, suffix); err != nil {
161				return err
162			}
163		}
164		// Leave the repository in the ONE state where every route agrees: the kept
165		// history living at the canonical key.
166		//
167		// Stopping here would only half-repair it. An adopted non-canonical store is
168		// reachable through the spelling that created it and invisible to every
169		// other -- a `cd`-and-run would find the canonical key empty and start a
170		// fresh brain beside the one just rescued, and the conflict would be back.
171		if kept.Key != set.Canonical.Key {
172			promoted, err := promoteRepoStorage(out, kept, set.Canonical, suffix)
173			if err != nil {
174				return err
175			}
176			fmt.Fprintf(out, "kept: %s, now stored under the canonical key %s\n", kept.Key, promoted.Key)
177			return nil
178		}
179		fmt.Fprintf(out, "kept: %s\n", kept.Key)
180		return nil
181	}
182	
183	// moveRepoStorageAside retires both halves of one store.
184	//
185	// The head store is a per-key DIRECTORY (it holds the export cursor alongside
186	// the setup record and the watch cursor), so it moves with its brain. Leaving
187	// the head behind would leave the conflict standing -- repoStorageContainsState
188	// counts either half, so a retired brain with a live head is still a second
189	// identity.
190	func moveRepoStorageAside(out io.Writer, storage repoStorage, suffix string) error {
191		for _, dir := range []string{storage.BrainDir, filepath.Dir(storage.HeadPath)} {
192			moved, err := moveRepoStoreAside(dir, suffix)
193			if err != nil {
194				return err
195			}
196			if moved != "" {
197				fmt.Fprintf(out, "moved aside: %s -> %s\n", dir, moved)
198			}
199		}
200		return nil
201	}
202	
203	// promoteRepoStorage renames a kept store onto the canonical key.
204	//
205	// Each half is one os.Rename within a single filesystem, so each is atomic:
206	// nothing is ever half-copied. The two renames are not atomic TOGETHER, and
207	// that is the residual risk. A crash between them leaves the brain at the
208	// canonical key and the head still at the old one -- which reads as two
209	// identities again, so the next command reports the same conflict and this same
210	// command repairs it. Nothing is lost either way, which is why this moves
211	// rather than copies and never removes.
212	func promoteRepoStorage(out io.Writer, kept, canonical repoStorage, suffix string) (repoStorage, error) {
213		// Whatever is sitting at the canonical paths is not the history being kept
214		// (the caller chose against it, or it is an empty shell left by a command
215		// that resolved the key without writing). Retire it rather than write over
216		// it.
217		if err := moveRepoStorageAside(out, canonical, suffix); err != nil {
218			return repoStorage{}, err
219		}
220		moves := [][2]string{
221			{kept.BrainDir, canonical.BrainDir},
222			{filepath.Dir(kept.HeadPath), filepath.Dir(canonical.HeadPath)},
223		}
224		for _, move := range moves {
225			from, to := move[0], move[1]
226			if _, err := os.Lstat(from); err != nil {
227				if errors.Is(err, os.ErrNotExist) {
228					continue
229				}
230				return repoStorage{}, fmt.Errorf("inspect %s: %w", from, err)
231			}
232			if err := os.MkdirAll(filepath.Dir(to), 0o700); err != nil {
233				return repoStorage{}, fmt.Errorf("create %s: %w", filepath.Dir(to), err)
234			}
235			if err := os.Rename(from, to); err != nil {
236				return repoStorage{}, fmt.Errorf("move %s to the canonical key: %w", from, err)
237			}
238			fmt.Fprintf(out, "promoted: %s -> %s\n", from, to)
239		}
240		return canonical, nil
241	}
242	
243	// moveRepoStoreAside renames dir to a timestamped sibling and reports the new
244	// name, or "" when there was nothing there. It refuses to overwrite an existing
245	// set-aside store rather than destroy a previous repair's copy.
246	func moveRepoStoreAside(dir, suffix string) (string, error) {
247		if _, err := os.Lstat(dir); err != nil {
248			if errors.Is(err, os.ErrNotExist) {
249				return "", nil
250			}
251			return "", fmt.Errorf("inspect %s: %w", dir, err)
252		}
253		target := dir + suffix
254		if _, err := os.Lstat(target); err == nil {
255			return "", fmt.Errorf("cannot move %s aside: %s already exists", dir, target)
256		} else if !errors.Is(err, os.ErrNotExist) {
257			return "", fmt.Errorf("inspect %s: %w", target, err)
258		}
259		if err := os.Rename(dir, target); err != nil {
260			return "", fmt.Errorf("move %s aside: %w", dir, err)
261		}
262		return target, nil
263	}
264

