140			}
141			return fmt.Errorf("--keep %q names no store for this repository; stores holding state: %s", keep, known)
142		}
143		if len(set.Populated) == 1 {
144			fmt.Fprintf(cmd.OutOrStdout(), "%s is already the only store for this repository; nothing to move aside\n", keep)
145			return nil
146		}
147	
148		now := time.Now
149		if opts.Now != nil {
150			now = opts.Now
151		}
152		suffix := repoIdentityConflictSuffix(now())
153		out := cmd.OutOrStdout()
154		var kept repoStorage
155		for _, storage := range set.Populated {
156			if storage.Key == keep {
157				kept = storage
158				continue
159			}
160			if err := moveRepoStorageAside(out, storage, suffix); err != nil {
161				return err
162			}
163		}
164		// Leave the repository in the ONE state where every route agrees: the kept
165		// history living at the canonical key.
166		//
167		// Stopping here would only half-repair it. An adopted non-canonical store is
168		// reachable through the spelling that created it and invisible to every
169		// other -- a `cd`-and-run would find the canonical key empty and start a
170		// fresh brain beside the one just rescued, and the conflict would be back.
171		if kept.Key != set.Canonical.Key {
172			promoted, err := promoteRepoStorage(out, kept, set.Canonical, suffix)
173			if err != nil {
174				return err
175			}
176			fmt.Fprintf(out, "kept: %s, now stored under the canonical key %s\n", kept.Key, promoted.Key)
177			return nil
178		}
179		fmt.Fprintf(out, "kept: %s\n", kept.Key)
180		return nil
181	}
182	
183	// moveRepoStorageAside retires both halves of one store.
184	//
