16	// symlinkedRepoFixture builds the shape the defect actually occurs in: a
17	// repository whose ANCESTOR is a symlink, so the same directory has two
18	// absolute spellings. This is /tmp on macOS -- a symlink to /private/tmp --
19	// which is why a repository created under /tmp was the everyday trigger.
20	//
21	// It returns the physical root (what git and getcwd report) and the logical
22	// root (what an absolute ENTIRE_REPO_ROOT through the alias spells).
23	func symlinkedRepoFixture(t *testing.T) (physical, logical string) {
24		t.Helper()
25		parent := t.TempDir()
26		realParent := filepath.Join(parent, "real-parent")
27		repoDir := filepath.Join(realParent, "repo")
28		if err := os.MkdirAll(repoDir, 0o700); err != nil {
29			t.Fatalf("mkdir repo: %v", err)
30		}
31		aliasParent := filepath.Join(parent, "alias-parent")
32		if err := os.Symlink(realParent, aliasParent); err != nil {
33			t.Skipf("directory symlinks are unavailable on this platform: %v", err)
34		}
35		resolved, err := filepath.EvalSymlinks(repoDir)
36		if err != nil {
37			t.Fatalf("resolve repo dir: %v", err)
38		}
39		logical = filepath.Join(aliasParent, "repo")
40		if resolved == logical {
41			t.Skip("platform collapsed the two spellings; there is nothing to split")
42		}
43		return resolved, logical
44	}
